<template>
  <div class="err-page" :class="{ 'err-page--minimal': !isAuthed }">
    <div class="err-hero">
      <div class="err-status-code" aria-hidden="true">{{ status_code }}</div>
      <h1 class="err-title">{{ heading }}</h1>
      <div class="err-body">
        <slot />
      </div>

      <!-- Authenticated: back + dashboard. Unauthenticated: go to login. -->
      <div class="err-actions">
        <template v-if="isAuthed">
          <q-btn
            unelevated
            no-caps
            icon="arrow_back"
            :label="t('back', 'Back')"
            :disable="!canGoBack"
            class="err-btn"
            @click="goBack"
          />
          <q-btn
            unelevated
            no-caps
            outline
            icon="dashboard"
            :label="t('dashboard', 'Dashboard')"
            class="err-btn"
            @click="$router.push('/dashboard')"
          />
        </template>
        <q-btn
          v-else
          unelevated
          no-caps
          icon-right="arrow_forward"
          :label="t('go_to_login', 'Go to login')"
          class="err-btn err-btn--primary"
          @click="$router.push('/login')"
        />
      </div>
    </div>

    <!-- Search + suggestions are authenticated-only. -->
    <div v-if="isAuthed" class="err-search-card">
      <label class="err-search-label">
        {{ t('errors_where_to', 'Where would you like to go?') }}
      </label>
      <div class="err-search-input-wrap" :class="{ focused: inputFocused }">
        <Icon icon="mdi:file-search-outline" class="err-search-icon" />
        <input
          ref="searchInput"
          v-model="query"
          type="text"
          :placeholder="t('search_all_pages', 'Type to find a page...')"
          class="err-search-input"
          @keydown.down.prevent="moveSelection(1)"
          @keydown.up.prevent="moveSelection(-1)"
          @keydown.enter.prevent="openSelected"
          @keydown.escape="query = ''"
          @focus="inputFocused = true"
          @blur="inputFocused = false"
        />
        <kbd v-if="!query" class="err-search-kbd">{{ cmdKeyLabel }}+K</kbd>
        <button
          v-else
          class="err-search-clear"
          :aria-label="t('clear', 'Clear')"
          @click="query = ''"
        >
          <Icon icon="mdi:close" class="size-4" />
        </button>
      </div>

      <ul v-if="query && results.length > 0" class="err-result-list" role="listbox">
        <li
          v-for="(result, index) in results"
          :key="result.entry.id"
          class="err-result-item"
          :class="{ selected: index === selectedIndex }"
          role="option"
          :aria-selected="index === selectedIndex"
          @click="navigateTo(result.entry)"
          @mouseenter="selectedIndex = index"
        >
          <div class="err-result-icon">
            <Icon :icon="result.entry.icon || 'mdi:file-document-outline'" class="size-4" />
          </div>
          <div class="err-result-content">
            <span class="err-result-label">{{ result.entry.label }}</span>
            <span class="err-result-category">{{ categoryLabel(result.entry.category) }}</span>
          </div>
          <Icon icon="mdi:chevron-right" class="err-result-arrow" />
        </li>
      </ul>

      <div v-else-if="!query && suggestions.length > 0" class="err-suggestions">
        <div class="err-suggestions-label">
          {{ t('errors_suggested_destinations', 'Jump to') }}
        </div>
        <div class="err-suggestion-grid">
          <button
            v-for="s in suggestions"
            :key="s.path"
            class="err-suggestion"
            @click="$router.push(s.path)"
          >
            <Icon :icon="s.icon" class="err-suggestion-icon" />
            <span class="err-suggestion-label">{{ t(s.labelKey, s.labelKey) }}</span>
          </button>
        </div>
      </div>

      <div v-else-if="query && results.length === 0" class="err-no-results">
        <Icon icon="mdi:file-search-outline" class="size-6" />
        <span>{{ t('no_results', 'No pages match') }} "{{ query }}"</span>
      </div>
    </div>
  </div>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import { LocalStorage } from 'quasar';
import { search, type SearchResult } from 'src/utils/route-search';
import { localizeRegistry, translateCategory, type IndexEntry } from 'src/utils/route-registry';

type Suggestion = { path: string; icon: string; labelKey: string };

// ─── User contribution point ─────────────────────────────────────────
// TODO: Curate the default destinations shown to *authenticated* users
// when the search input is empty. Shown as a grid of quick-jump buttons.
//
// Guidance:
//   - Pick routes that exist and do NOT require URL params (no :id).
//   - Order matters — first = most prominent.
//   - Use labelKey values that exist in the i18n/Tolgee catalogs;
//     the template falls back to the raw key if no translation exists.
//   - Icons must be in the MDI bundle (src/icons/mdi-selective.json).
//   - Keep it tight: 4–6 entries max.
// ─────────────────────────────────────────────────────────────────────
const SUGGESTIONS: Suggestion[] = [
  // TODO: fill these in — which routes belong on an error page?
];

export default defineComponent({
  name: 'ErrorPage',
  props: {
    heading: { type: String, default: '' },
    status_code: { type: String, default: '500' },
    // Force the shell-less "login-style" view regardless of auth state.
    // Used by NetworkError: when the backend is down, the search /
    // navigation affordances are misleading — keep the page minimal.
    minimal: { type: Boolean, default: false },
  },
  data() {
    return {
      query: '',
      results: [] as SearchResult[],
      selectedIndex: 0,
      debounceTimer: null as ReturnType<typeof setTimeout> | null,
      inputFocused: false,
      suggestions: SUGGESTIONS,
      tokenAuthed: !!(LocalStorage.getItem('token_details') as any)?.access_token,
    };
  },
  computed: {
    /** Registry with label/description in the active locale. */
    localizedRegistry(): IndexEntry[] {
      return localizeRegistry((key, fallback) => this.t(key, fallback));
    },
    isAuthed(): boolean {
      return !this.minimal && this.tokenAuthed;
    },
    canGoBack(): boolean {
      return window.history.length > 1;
    },
    cmdKeyLabel(): string {
      const isMac = typeof navigator !== 'undefined' && /Mac|iPhone|iPad/i.test(navigator.platform);
      return isMac ? '⌘' : 'Ctrl';
    },
  },
  watch: {
    query(val: string) {
      this.selectedIndex = 0;
      if (this.debounceTimer) clearTimeout(this.debounceTimer);
      this.debounceTimer = setTimeout(() => {
        const trimmed = val.trim();
        // Reuse the exact engine QuickSearchModal uses, over the localized registry.
        const raw = trimmed ? search(trimmed, { maxResults: 12, registry: this.localizedRegistry }) : [];
        // Error page can only navigate to simple routes — skip entries
        // needing a picker (doc type / doc id) or URL params.
        this.results = raw
          .filter((r) => !r.entry.paramResolver && r.entry.path && !r.entry.path.includes(':'))
          .slice(0, 8);
      }, 100);
    },
  },
  mounted() {
    if (this.isAuthed) {
      this.$nextTick(() => (this.$refs.searchInput as HTMLInputElement)?.focus());
    }
  },
  unmounted() {
    if (this.debounceTimer) clearTimeout(this.debounceTimer);
  },
  methods: {
    // Translate with fallback — `$t()` returns the raw key when no translation
    // exists, so `$t('key') || 'fallback'` never reaches the fallback. Use
    // `$te()` to check existence first.
    t(key: string, fallback: string): string {
      return this.$te(key) ? (this.$t(key) as string) : fallback;
    },
    moveSelection(delta: number) {
      if (this.results.length === 0) return;
      this.selectedIndex = Math.max(
        0,
        Math.min(this.results.length - 1, this.selectedIndex + delta),
      );
    },
    openSelected() {
      const r = this.results[this.selectedIndex];
      if (r) this.navigateTo(r.entry);
    },
    categoryLabel(category: string): string {
      return translateCategory(category, (key, fallback) => this.t(key, fallback));
    },
    navigateTo(entry: IndexEntry) {
      if (!entry.path) return;
      this.$router.push(entry.path);
    },
    goBack() {
      if (this.canGoBack) this.$router.go(-1);
      else this.$router.push('/dashboard');
    },
  },
});
</script>

